  static final _hrRe = RegExp(r'^\s{0,3}((-\s*){3,}|(_\s*){3,}|(\*\s*){3,})$');
  static final _quoteRe = RegExp(r'^(\s*)>( |$)(.*)$');
  static final _bulletRe = RegExp(r'^(\s*)([-*+]|\d{1,3}[.)])\s+(.*)$');
