/// [MemoryExecutionEnv] plus the rename capability: exercises the
/// rotation path the production env (LocalExecutionEnv) takes, where the
/// oversized log moves to `fa.log.1` instead of being truncated.
final class _RenamingMemoryEnv extends MemoryExecutionEnv
    implements RenamableFileSystem {
  _RenamingMemoryEnv() : super(cwd: '/work');

  @override
  Future<Result<void, FileError>> renamePath(String from, String to) async {
    final content = await readBinaryFile(from);
    final bytes = content.valueOrNull;
    if (bytes == null) {
      return Err(
        FileError(FileErrorCode.notFound, 'no such file', path: from),
      );
    }
    final written = await writeBinaryFile(to, bytes);
    if (written.isErr) {
      return Err(written.errorOrNull ?? const FileError(FileErrorCode.unknown, 'write failed'));
    }
    await remove(from);
    return const Ok(null);
  }
}

