    }
    final written = await _delegate.writeBinaryFile(to, bytes);
    if (written.isErr) {
      return Err(
        written.errorOrNull ?? const FileError(FileErrorCode.unknown, 'write failed'),
      );
    }
    await _delegate.remove(from);
    return const Ok(null);
  }
