/// parent directories automatically, matching the `dart:io` implementation.
final class MemoryFileSystem
    implements
        FileSystem,
        RangedReadFileSystem,
        FsSnapshotExporter,
        RenamableFileSystem {
  /// Creates a [MemoryFileSystem] rooted at [cwd] (default `/`).
  MemoryFileSystem({this.cwd = '/'}) {
    _dirs.add('/');
  }

    if (isFile) {
