    this._delegate,
    CubeSpec? spec, {
    String? homeDir,
    String? workspaceRoot,
    CubeFsProbe? pathProbe,
    String? os,
    void Function(String message)? onWarning,
  }) : _homeDir = homeDir,
       _workspaceRoot = workspaceRoot,
       _pathProbe = pathProbe,
       _os = os,
